#include <stdio.h>

// 值传递，无法交换
void swap(int a, int b) {
    int t = a; a = b; b = t;
}

int main() {
    int x = 3, y = 5;
    swap(x, y);
    printf("%d %d\n", x, y);  // 3 5，没变
    return 0;
}

#include <stdio.h>

// 返回计算结果
int square(int n) {
    return n * n;
}

// static计数器
int counter() {
    static int count = 0;
    return ++count;
}

int main() {
    printf("%d\n", square(5));   // 25
    printf("%d\n", counter());    // 1
    printf("%d\n", counter());    // 2
    return 0;
}

