// 综合示例：函数+数组
#include <stdio.h>

void printArr(int arr[], int n) {
    for (int i = 0; i < n; i++)
        printf("%d ", arr[i]);
    printf("\n");
}

int sumArr(int arr[], int n) {
    int s = 0;
    for (int i = 0; i < n; i++) s += arr[i];
    return s;
}

int main() {
    int a[5] = {1,2,3,4,5};
    printArr(a, 5);
    printf("sum=%d\n", sumArr(a, 5));
    return 0;
}

#include <stdio.h>
#define MAX 50

float scores[MAX];
int n = 0;

void input() {
    printf("输入学生人数: ");
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        printf("学生%d成绩: ", i+1);
        scanf("%f", &scores[i]);
    }
}

void stat() {
    float sum = 0, max = scores[0], min = scores[0];
    for (int i = 0; i < n; i++) {
        sum += scores[i];
        if (scores[i] > max) max = scores[i];
        if (scores[i] < min) min = scores[i];
    }
    printf("平均:%.1f 最高:%.1f 最低:%.1f\n", sum/n, max, min);
}

int main() {
    input();
    stat();
    return 0;
}
